class Solution {
public:
    int minimumWhiteTiles(string floor, int numCarpets, int carpetLen) {
        int n = floor.size();
        vector<vector<int>> dp(numCarpets + 1, vector<int>(n + 1, 0));
        for (int j = 1; j <= n; j++) {
            dp[0][j] = dp[0][j - 1] + (floor[j - 1] == '1' ? 1 : 0);
        }
        for (int i = 1; i <= numCarpets; i++) {
            for (int j = 1; j <= n; j++) {
                int uncovered = dp[i][j - 1] + (floor[j - 1] == '1' ? 1 : 0);
                int covered = dp[i - 1][max(0, j - carpetLen)];
                dp[i][j] = min(uncovered, covered);
            }
        }
        return dp[numCarpets][n];
    }
};

class Solution {
    public int minimumWhiteTiles(String floor, int numCarpets, int carpetLen) {
        int n = floor.length();
        int[][] dp = new int[numCarpets + 1][n + 1];
        for (int j = 1; j <= n; j++) {
            dp[0][j] = dp[0][j - 1] + (floor.charAt(j - 1) == '1' ? 1 : 0);
        }
        for (int i = 1; i <= numCarpets; i++) {
            for (int j = 1; j <= n; j++) {
                int uncovered = dp[i][j - 1] + (floor.charAt(j - 1) == '1' ? 1 : 0);
                int covered = dp[i - 1][Math.max(0, j - carpetLen)];
                dp[i][j] = Math.min(uncovered, covered);
            }
        }
        return dp[numCarpets][n];
    }
}

