var minimumWhiteTiles = function(floor, numCarpets, carpetLen) {
    const n = floor.length;
    const dp = Array.from({ length: numCarpets + 1 }, () => new Array(n + 1).fill(0));
    for (let j = 1; j <= n; j++) {
        dp[0][j] = dp[0][j - 1] + (floor[j - 1] === '1' ? 1 : 0);
    }
    for (let i = 1; i <= numCarpets; i++) {
        for (let j = 1; j <= n; j++) {
            const uncovered = dp[i][j - 1] + (floor[j - 1] === '1' ? 1 : 0);
            const covered = dp[i - 1][Math.max(0, j - carpetLen)];
            dp[i][j] = Math.min(uncovered, covered);
        }
    }
    return dp[numCarpets][n];
};
